const input = $input.first().json;
const body = input.body || input;

const receivedAt = new Date().toISOString();
const ticketId = body.ticketId || `T-${Date.now()}`;
const customerName = body.customerName || body.name || 'Unknown customer';
const customerEmail = String(body.customerEmail || body.email || '').toLowerCase().trim();
const subject = body.subject || 'No subject provided';
const message = body.message || body.description || body.text || '';

if (!message.trim()) {
  throw new Error('Ticket message is required.');
}

let redactedText = `${subject}\n\n${message}`;
let redactionCount = 0;

function redact(pattern, label) {
  redactedText = redactedText.replace(pattern, () => {
    redactionCount += 1;
    return `[REDACTED_${label}]`;
  });
}

redact(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, 'EMAIL');
redact(/(?:\+?\d[\d\s().-]{7,}\d)/g, 'PHONE');
redact(/\b(?:\d[ -]*?){13,19}\b/g, 'CARD_LIKE_NUMBER');
redact(/\b(?:sk|pk|rk|api|key|token)[_-]?[a-z0-9]{16,}\b/gi, 'SECRET_LIKE_TOKEN');

return [{
  json: {
    receivedAt,
    ticketId,
    customerName,
    customerEmail,
    subject,
    originalMessage: message,
    redactedText: redactedText.slice(0, 4000),
    redactionCount
  }
}];

const ticket = $('Validate And Redact Ticket').first().json;
const duplicate = $('Find Open Duplicate Ticket').first().json || {};
const customer = $('Lookup Customer Context').first().json || {};
const kbItems = $input.all().map(item => item.json).filter(row => row.Title || row.Keywords || row.URL);

const lowerTicket = `${ticket.subject}\n${ticket.redactedText}`.toLowerCase();
const matches = kbItems
  .map(row => {
    const keywords = String(row.Keywords || '').split(',').map(k => k.trim()).filter(Boolean);
    const score = keywords.filter(k => lowerTicket.includes(k.toLowerCase())).length;
    return { row, score };
  })
  .filter(match => match.score > 0)
  .sort((a, b) => b.score - a.score)
  .slice(0, 3)
  .map(match => ({
    title: match.row.Title || '',
    url: match.row.URL || '',
    score: match.score
  }));

const customerTier = customer.Tier || 'Standard';
const accountManager = customer['Account Manager'] || 'Support team';
const duplicateTicketId = duplicate['Ticket ID'] || '';

return [{
  json: {
    ...ticket,
    customerTier,
    accountManager,
    duplicateOpenTicket: duplicateTicketId,
    hasDuplicateOpenTicket: Boolean(duplicateTicketId),
    relatedArticles: matches,
    relatedArticle: matches[0]?.title || 'No matching article found',
    relatedArticleUrl: matches[0]?.url || ''
  }
}];

