const ai = $input.first().json;
const base = $('Match Knowledge Base Articles').first().json;

let text = '';
if (typeof ai.output_text === 'string') {
  text = ai.output_text;
} else if (Array.isArray(ai.output)) {
  text = ai.output.flatMap(item => item.content || []).map(content => content.text || '').join('\n');
}

let parsed;
try {
  parsed = JSON.parse(text);
} catch (error) {
  parsed = {
    category: 'General',
    sentiment: 'Unknown',
    urgency: 'Medium',
    confidence: 0.4,
    summary: 'AI response could not be parsed. Human review recommended.',
    suggestedReply: 'Thanks for contacting support. Our team has received your request and will review it shortly.',
    escalationReason: 'AI response parsing failed.'
  };
}

const category = parsed.category || 'General';
const urgency = parsed.urgency || 'Medium';
const confidence = Number(parsed.confidence ?? 0.5);
const vipCustomer = ['VIP', 'Enterprise', 'Premium'].includes(base.customerTier);
const escalationCategories = ['Billing', 'Refund', 'Security', 'Account Access', 'Complaint'];

let slaHours = 72;
if (urgency === 'High') slaHours = 4;
else if (urgency === 'Medium') slaHours = 24;
if (vipCustomer) slaHours = Math.min(slaHours, 8);

const slaDue = new Date(Date.now() + slaHours * 60 * 60 * 1000).toISOString();
const lowConfidence = confidence < 0.7;
const escalationNeeded = base.hasDuplicateOpenTicket || lowConfidence || urgency === 'High' || vipCustomer || escalationCategories.includes(category);

const reasons = [];
if (base.hasDuplicateOpenTicket) reasons.push(`Duplicate open ticket ${base.duplicateOpenTicket}`);
if (lowConfidence) reasons.push('Low AI confidence');
if (urgency === 'High') reasons.push('High urgency');
if (vipCustomer) reasons.push(`${base.customerTier} customer`);
if (escalationCategories.includes(category)) reasons.push(`${category} category`);
if (parsed.escalationReason) reasons.push(parsed.escalationReason);

return [{
  json: {
    ...base,
    category,
    sentiment: parsed.sentiment || 'Unknown',
    urgency,
    confidence,
    slaHours,
    slaDueAt: slaDue,
    summary: parsed.summary || 'No summary returned.',
    suggestedReply: parsed.suggestedReply || 'Thanks for contacting support. Our team will review your request shortly.',
    escalationNeeded,
    escalationReason: reasons.length ? [...new Set(reasons)].join(', ') : 'No escalation needed',
    status: 'Open'
  }
}];

const now = new Date();
const rows = $input.all().map(item => item.json).filter(row => row['Ticket ID']);
const risky = rows
  .map(row => {
    const due = new Date(row['SLA Due At']);
    const hoursLeft = (due - now) / 36e5;
    return { row, hoursLeft };
  })
  .filter(item => item.hoursLeft <= 4)
  .sort((a, b) => a.hoursLeft - b.hoursLeft);

if (!risky.length) {
  return [{ json: { hasSlaRisk: false, digest: 'No open tickets are overdue or within 4 hours of SLA breach.' } }];
}

const digest = risky.map(item => {
  const row = item.row;
  const label = item.hoursLeft < 0 ? `${Math.abs(item.hoursLeft).toFixed(1)}h overdue` : `${item.hoursLeft.toFixed(1)}h left`;
  return `- ${row['Ticket ID']} | ${row['Urgency']} | ${row['Category']} | ${label} | ${row['Customer Email']}`;
}).join('\n');

return [{
  json: {
    hasSlaRisk: true,
    digest,
    ticketCount: risky.length
  }
}];
